macro_rules! deps {
    () => {
        Statement!();
        Named!();
        Result!();
        ToSql!();
        ParamsFromIter!();
        Connection!();
    };
}

macro_rules! Params {
    () => {
        deps!();
        # [doc = " Trait used for [sets of parameter][params] passed into SQL"] # [doc = " statements/queries."] # [doc = ""] # [doc = " [params]: https://www.sqlite.org/c3ref/bind_blob.html"] # [doc = ""] # [doc = " Note: Currently, this trait can only be implemented inside this crate."] # [doc = " Additionally, it's methods (which are `doc(hidden)`) should currently not be"] # [doc = " considered part of the stable API, although it's possible they will"] # [doc = " stabilize in the future."] # [doc = ""] # [doc = " # Passing parameters to SQLite"] # [doc = ""] # [doc = " Many functions in this library let you pass parameters to SQLite. Doing this"] # [doc = " lets you avoid any risk of SQL injection, and is simpler than escaping"] # [doc = " things manually. Aside from deprecated functions and a few helpers, this is"] # [doc = " indicated by the function taking a generic argument that implements `Params`"] # [doc = " (this trait)."] # [doc = ""] # [doc = " ## Positional parameters"] # [doc = ""] # [doc = " For cases where you want to pass a list of parameters where the number of"] # [doc = " parameters is known at compile time, this can be done in one of the"] # [doc = " following ways:"] # [doc = ""] # [doc = " - For small lists of parameters up to 16 items, they may alternatively be"] # [doc = "   passed as a tuple, as in `thing.query((1, \"foo\"))`."] # [doc = "   This is somewhat inconvenient for a single item, since you need a"] # [doc = "   weird-looking trailing comma: `thing.query((\"example\",))`. That case is"] # [doc = "   perhaps more cleanly expressed as `thing.query([\"example\"])`."] # [doc = ""] # [doc = " - Using the [`rusqlite::params!`](crate::params!) macro, e.g."] # [doc = "   `thing.query(rusqlite::params![1, \"foo\", bar])`. This is mostly useful for"] # [doc = "   heterogeneous lists where the number of parameters greater than 16, or"] # [doc = "   homogeneous lists of parameters where the number of parameters exceeds 32."] # [doc = ""] # [doc = " - For small homogeneous lists of parameters, they can either be passed as:"] # [doc = ""] # [doc = "     - an array, as in `thing.query([1i32, 2, 3, 4])` or `thing.query([\"foo\","] # [doc = "       \"bar\", \"baz\"])`."] # [doc = ""] # [doc = "     - a reference to an array of references, as in `thing.query(&[\"foo\","] # [doc = "       \"bar\", \"baz\"])` or `thing.query(&[&1i32, &2, &3])`."] # [doc = "       (Note: in this case we don't implement this for slices for coherence"] # [doc = "       reasons, so it really is only for the \"reference to array\" types —"] # [doc = "       hence why the number of parameters must be <= 32, or you need to"] # [doc = "       reach for `rusqlite::params!`)"] # [doc = ""] # [doc = "   Unfortunately, in the current design it's not possible to allow this for"] # [doc = "   references to arrays of non-references (e.g. `&[1i32, 2, 3]`). Code like"] # [doc = "   this should instead either use `params!`, an array literal, a `&[&dyn"] # [doc = "   ToSql]` or if none of those work, [`ParamsFromIter`]."] # [doc = ""] # [doc = " - As a slice of `ToSql` trait object references, e.g. `&[&dyn ToSql]`. This"] # [doc = "   is mostly useful for passing parameter lists around as arguments without"] # [doc = "   having every function take a generic `P: Params`."] # [doc = ""] # [doc = " ### Example (positional)"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " # use rusqlite::{Connection, Result, params};"] # [doc = " fn update_rows(conn: &Connection) -> Result<()> {"] # [doc = "     let mut stmt = conn.prepare(\"INSERT INTO test (a, b) VALUES (?1, ?2)\")?;"] # [doc = ""] # [doc = "     // Using a tuple:"] # [doc = "     stmt.execute((0, \"foobar\"))?;"] # [doc = ""] # [doc = "     // Using `rusqlite::params!`:"] # [doc = "     stmt.execute(params![1i32, \"blah\"])?;"] # [doc = ""] # [doc = "     // array literal — non-references"] # [doc = "     stmt.execute([2i32, 3i32])?;"] # [doc = ""] # [doc = "     // array literal — references"] # [doc = "     stmt.execute([\"foo\", \"bar\"])?;"] # [doc = ""] # [doc = "     // Slice literal, references:"] # [doc = "     stmt.execute(&[&2i32, &3i32])?;"] # [doc = ""] # [doc = "     // Note: The types behind the references don't have to be `Sized`"] # [doc = "     stmt.execute(&[\"foo\", \"bar\"])?;"] # [doc = ""] # [doc = "     // However, this doesn't work (see above):"] # [doc = "     // stmt.execute(&[1i32, 2i32])?;"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## Named parameters"] # [doc = ""] # [doc = " SQLite lets you name parameters using a number of conventions (\":foo\","] # [doc = " \"@foo\", \"$foo\"). You can pass named parameters in to SQLite using rusqlite"] # [doc = " in a few ways:"] # [doc = ""] # [doc = " - Using the [`rusqlite::named_params!`](crate::named_params!) macro, as in"] # [doc = "   `stmt.execute(named_params!{ \":name\": \"foo\", \":age\": 99 })`. Similar to"] # [doc = "   the `params` macro, this is most useful for heterogeneous lists of"] # [doc = "   parameters, or lists where the number of parameters exceeds 32."] # [doc = ""] # [doc = " - As a slice of `&[(&str, &dyn ToSql)]`. This is what essentially all of"] # [doc = "   these boil down to in the end, conceptually at least. In theory, you can"] # [doc = "   pass this as `stmt`."] # [doc = ""] # [doc = " - As array references, similar to the positional params. This looks like"] # [doc = "   `thing.query(&[(\":foo\", &1i32), (\":bar\", &2i32)])` or"] # [doc = "   `thing.query(&[(\":foo\", \"abc\"), (\":bar\", \"def\")])`."] # [doc = ""] # [doc = " Note: Unbound named parameters will be left to the value they previously"] # [doc = " were bound with, falling back to `NULL` for parameters which have never been"] # [doc = " bound."] # [doc = ""] # [doc = " ### Example (named)"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " # use rusqlite::{Connection, Result, named_params};"] # [doc = " fn insert(conn: &Connection) -> Result<()> {"] # [doc = "     let mut stmt = conn.prepare(\"INSERT INTO test (key, value) VALUES (:key, :val)\")?;"] # [doc = "     // Using `rusqlite::params!`:"] # [doc = "     stmt.execute(named_params! { \":key\": \"one\", \":val\": 2 })?;"] # [doc = "     // Alternatively:"] # [doc = "     stmt.execute(&[(\":key\", \"three\"), (\":val\", \"four\")])?;"] # [doc = "     // Or:"] # [doc = "     stmt.execute(&[(\":key\", &100), (\":val\", &200)])?;"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## No parameters"] # [doc = ""] # [doc = " You can just use an empty tuple or the empty array literal to run a query"] # [doc = " that accepts no parameters."] # [doc = ""] # [doc = " ### Example (no parameters)"] # [doc = ""] # [doc = " The empty tuple:"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " # use rusqlite::{Connection, Result, params};"] # [doc = " fn delete_all_users(conn: &Connection) -> Result<()> {"] # [doc = "     // You may also use `()`."] # [doc = "     conn.execute(\"DELETE FROM users\", ())?;"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " The empty array:"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " # use rusqlite::{Connection, Result, params};"] # [doc = " fn delete_all_users(conn: &Connection) -> Result<()> {"] # [doc = "     // Just use an empty array (e.g. `[]`) for no params."] # [doc = "     conn.execute(\"DELETE FROM users\", [])?;"] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## Dynamic parameter list"] # [doc = ""] # [doc = " If you have a number of parameters which is unknown at compile time (for"] # [doc = " example, building a dynamic query at runtime), you have two choices:"] # [doc = ""] # [doc = " - Use a `&[&dyn ToSql]`. This is often annoying to construct if you don't"] # [doc = "   already have this type on-hand."] # [doc = " - Use the [`ParamsFromIter`] type. This essentially lets you wrap an"] # [doc = "   iterator some `T: ToSql` with something that implements `Params`. The"] # [doc = "   usage of this looks like `rusqlite::params_from_iter(something)`."] # [doc = ""] # [doc = " A lot of the considerations here are similar either way, so you should see"] # [doc = " the [`ParamsFromIter`] documentation for more info / examples."] pub trait Params : Sealed { # [doc (hidden)] fn __bind_in (self , stmt : & mut Statement < '_ >) -> Result < () > ; }
    };
}

Params!();